import { describe, expect, it } from "vitest";
import primary from "./fixtures/blackjackinfo-charts.json";
import secondary from "./fixtures/wizard-charts.json";
import { DEFAULT_RULES, type RuleSet } from "./rules";
import { DEALER_UPCARDS, strategyChart, type ChartCode, type StrategyChart } from "./strategy";

// Frozen independent source data and the one source disagreement are documented in
// fixtures/README.md. Neither fixture was generated by strategyChart.
const codes: Record<ChartCode, string> = {
  H: "H",
  S: "S",
  D: "D",
  Ds: "d",
  P: "P",
  Rh: "R",
  Rs: "r",
  Rp: "p",
};
function packed(chart: StrategyChart): string {
  const rows = [
    ...Object.entries(chart.hard)
      .filter(([key]) => Number(key) >= 5 && Number(key) <= 18)
      .map(([, row]) => row),
    ...Object.entries(chart.soft)
      .filter(([key]) => Number(key) >= 13 && Number(key) <= 20)
      .map(([, row]) => row),
    ...["2", "3", "4", "5", "6", "7", "8", "9", "10", "A"].map(
      (rank) => chart.pairs[rank as keyof typeof chart.pairs],
    ),
  ];
  return rows.map((row) => DEALER_UPCARDS.map((upcard) => codes[row[upcard]]).join("")).join(" ");
}

const families = Object.entries(primary).map(([key, published]) => {
  const [decks, soft17, das, double, surrender, peek] = key.split("/");
  const rules: RuleSet = {
    ...DEFAULT_RULES,
    decks: Number(decks),
    dealerSoft17: soft17 === "H17" ? "hit" : "stand",
    doubleAfterSplit: das === "DAS",
    doubleRule: double === "all" ? "any" : double === "d9" ? "9-11" : "10-11",
    surrender: surrender === "ns" ? "none" : surrender === "ls" ? "late" : "early",
    dealerPeek: peek === "peek",
  };
  return { key, published, rules };
});

describe("every published chart family", () => {
  it("contains all 288 reference families and 252 distinct charts", () => {
    expect(families).toHaveLength(288);
    expect(new Set(Object.values(primary)).size).toBe(252);
  });
  it.each(families)(
    "$key covers every supported deck, split, ace and payout setting",
    ({ rules, published }) => {
      for (const decks of rules.decks === 4 ? [4, 5, 6, 7, 8] : [rules.decks]) {
        for (const maxSplitHands of [1, 2, 3, 4]) {
          for (const resplitAces of [false, true]) {
            for (const oneCardToSplitAces of [false, true]) {
              for (const blackjackPayout of ["3:2", "6:5"] as const) {
                expect(
                  packed(
                    strategyChart({
                      ...rules,
                      decks,
                      maxSplitHands,
                      resplitAces,
                      oneCardToSplitAces,
                      blackjackPayout,
                    }),
                  ),
                ).toBe(published);
              }
            }
          }
        }
      }
    },
  );
});

const disputed = "2/H17/DAS/all/ls/peek";
describe("Wizard calculator independently cross-checks 36 shared configurations", () => {
  it.each(Object.entries(secondary))("%s", (key, published) => {
    const expected = primary[key as keyof typeof primary];
    if (key !== disputed) {
      expect(published).toBe(expected);
      return;
    }
    // Wizard's dedicated surrender article explicitly exempts double-deck DAS 8,8
    // against Ace. Its calculator misses that exception; retain its raw output.
    const sourceRows = published.split(" ");
    const expectedRows = expected.split(" ");
    expect(sourceRows[28]).toBe("PPPPPPPPPp");
    expect(expectedRows[28]).toBe("PPPPPPPPPP");
    sourceRows[28] = "PPPPPPPPPP";
    expect(sourceRows).toEqual(expectedRows);
  });
});
